"""Generates include/kivy_nui_gl.h from Kivy's own GL declarations.

    python3 generate_kivy_nui_gl.py ../../kivy2x > include/kivy_nui_gl.h

The function table is `GLES2_Context` in kivy/graphics/cgl.pxd, member for
member; the constants are the `int GL_*` names cgl.pxd declares, with values
from kivy/include/common_subset.h and gl_redirect.h. Rerun it when cgl.pxd
changes.
"""
import re
import sys

kivy = sys.argv[1]
pxd = open(f"{kivy}/kivy/graphics/cgl.pxd").read()
defs = (open(f"{kivy}/kivy/include/common_subset.h").read()
        + open(f"{kivy}/kivy/include/gl_redirect.h").read())

extern = pxd.split("ctypedef struct GLES2_Context")[0]
values = dict(re.findall(r"#define\s+(GL_[A-Z0-9_]+)\s+(\S+)", defs))
consts = []
for name in re.findall(r"^\s+int\s+(GL_[A-Z0-9_]+)\s*$", extern, re.M):
    # cgl.pxd's GL_ANT_COLOR & co. are a typo for GL_CONSTANT_*, and have no
    # value anywhere; nothing in Kivy uses them.
    if name in values and name not in consts:
        consts.append(name)

body = pxd.split("ctypedef struct GLES2_Context:")[1].split("\n\n")[0]
funcs = []
for line in body.strip().splitlines():
    line = line.strip().replace("__stdcall ", "").replace(" nogil", "")
    funcs.append(re.sub(r"\(\s+", "(", re.sub(r"\s+\)", ")", line)))

types = {
    "GLvoid": "void", "GLchar": "char", "GLenum": "KivyNUIGLenum",
    "GLboolean": "KivyNUIGLboolean", "GLbitfield": "KivyNUIGLbitfield",
    "GLint": "KivyNUIGLint", "GLsizei": "KivyNUIGLsizei",
    "GLuint": "KivyNUIGLuint", "GLubyte": "KivyNUIGLubyte",
    "GLfloat": "KivyNUIGLfloat", "GLclampf": "KivyNUIGLclampf",
    "GLintptr": "KivyNUIGLintptr", "GLsizeiptr": "KivyNUIGLsizeiptr",
}


def retype(s):
    return re.sub(r"\bGL[a-z]+\b", lambda m: types[m.group(0)], s)


print(r'''/*
 * kivy_nui_gl.h — the GPU half of the shared C api. GENERATED by
 * generate_kivy_nui_gl.py from Kivy's cgl.pxd; edit the generator, not this.
 *
 * Kivy draws everything — canvas, instructions, Fbo, Texture, Shader —
 * through one table of GLES2 functions (`GLES2_Context`, kivy/graphics/
 * cgl.pxd), filled by a cgl backend. `KivyNUIGL` is that table. The host
 * implements it on its GPU and registers it (`KivyNUIHost.gl`);
 * `cgl_nui.pyx` copies it into Kivy's table, the way `cgl_angle.pyx` fills
 * it from eglGetProcAddress. Nothing above the table changes.
 *
 * What the host's implementation must do, so Kivy sees plain GLES2:
 *
 *   - Framebuffer 0 is the shared image: the VkImage of KivyRepresentable's
 *     shader node. Its size is `KivyNUIWindowMetrics.pixel_width/height`.
 *     Kivy finishes a frame into it with `kivy_nui_present`.
 *   - GL's conventions hold as Kivy expects them: viewport/scissor/
 *     glReadPixels origin bottom-left, texture row 0 = first row uploaded,
 *     clip space y up. Any flip Vulkan needs is the host's business (in its
 *     pipeline or when the shader node samples the image), never Kivy's.
 *   - Shaders arrive as GLSL source with no `#version` line, guarded by
 *     `#ifdef GL_ES` (kivy/data/glsl/header.vs/.fs); the host compiles them
 *     to SPIR-V by glCompileShader/glLinkProgram. Kivy asks for attribute
 *     locations after linking (glGetAttribLocation, shader.pyx) and sets
 *     uniforms by location through glUniform*.
 *   - glGetString answers as an OpenGL ES 2.0 implementation.
 *   - A function the host does not implement yet is NULL; `cgl_nui.pyx`
 *     reports which, and Kivy's own `gl_check` logs it.
 *
 * Main thread only, like every GL call Kivy makes.
 */

#ifndef KIVY_NUI_GL_H
#define KIVY_NUI_GL_H

#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/* MARK: - Types */

/* GLES2's types under our own names, so this header can sit next to any
   system GL header (Kivy's cgl_nui.pyx includes both). Same sizes and
   signedness as khrplatform.h on every target. */
typedef unsigned int  KivyNUIGLenum;
typedef unsigned char KivyNUIGLboolean;
typedef unsigned int  KivyNUIGLbitfield;
typedef int           KivyNUIGLint;
typedef int           KivyNUIGLsizei;
typedef unsigned int  KivyNUIGLuint;
typedef unsigned char KivyNUIGLubyte;
typedef float         KivyNUIGLfloat;
typedef float         KivyNUIGLclampf;
typedef intptr_t      KivyNUIGLintptr;
typedef intptr_t      KivyNUIGLsizeiptr;

/* MARK: - Constants */

/* Every `int GL_*` cgl.pxd declares, with its GLES2 value. */''')
width = max(len(n) for n in consts) + len("KIVY_NUI_")
for n in consts:
    print(f"#define {('KIVY_NUI_' + n).ljust(width)} {values[n]}")
print('''
/* MARK: - Function table */

/* One member per `GLES2_Context` member, same name, same signature. */
typedef struct KivyNUIGL {''')
for f in funcs:
    print("    " + retype(f) + ";")
print('''} KivyNUIGL;

#ifdef __cplusplus
}
#endif

#endif /* KIVY_NUI_GL_H */''')
